"use client";

import { useState } from "react";
import {
  FileText,
  Link2,
  Sparkles,
  ChevronDown,
  BarChart3,
  AlertTriangle,
  CheckCircle2,
  Lightbulb,
  Copy,
  Download,
  RotateCcw,
} from "lucide-react";

const contentTypes = [
  "General Post",
  "Social Media Post",
  "Advertisement",
  "Tourism Content",
  "Website Content",
  "Educational Material",
  "Festival Content",
  "Food & Cuisine",
  "Traditional Arts",
  "Customs & Traditions",
];

const targetAudiences = [
  "International Audience",
  "International Students",
  "Tourists",
  "General Public",
  "Academic Audience",
];

type EvaluationFormProps = {
  content?: string;
  onContentChange?: (content: string) => void;
};

export default function EvaluationForm({
  content = "",
  onContentChange,
}: EvaluationFormProps) {
  const [inputMode, setInputMode] = useState<"text" | "url">("text");
  const [url, setUrl] = useState("");
  const [contentType, setContentType] = useState("General Post");
  const [targetAudience, setTargetAudience] = useState(
    "International Audience"
  );
  const [evaluated, setEvaluated] = useState(false);

  const maxLength = 2000;

  const handleContentChange = (
    e: React.ChangeEvent<HTMLTextAreaElement>
  ) => {
    const value = e.target.value.slice(0, maxLength);
    onContentChange?.(value);
  };

  const handleEvaluate = () => {
    setEvaluated(true);
  };

  const handleReset = () => {
    onContentChange?.("");
    setUrl("");
    setEvaluated(false);
  };

  const handleCopy = async () => {
    const result = `Overall Score: 78/100
Risk Level: Moderate Risk

Cultural Accuracy: 85
Avoids Generalization: 70
Bias & Stereotypes: 60
Cross-cultural Clarity: 80
Misunderstanding Risk: 65
Communication Quality: 90`;

    try {
      await navigator.clipboard.writeText(result);
    } catch {
      // Clipboard may be unavailable in some browsers.
    }
  };

  return (
    <div className="grid gap-6 xl:grid-cols-[1.08fr_0.92fr]">
      {/* ================= LEFT COLUMN ================= */}
      <div className="min-w-0 space-y-6">
        {/* Evaluation Card */}
        <section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
          {/* Header */}
          <div className="mb-6 flex items-start gap-3">
            <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-blue-50">
              <FileText className="h-5 w-5 text-blue-600" />
            </div>

            <div>
              <h2 className="text-xl font-bold tracking-tight text-slate-900">
                Evaluate Chinese Cultural Content
              </h2>

              <p className="mt-1 text-sm leading-6 text-slate-500">
                Enter cultural content for AI-powered evaluation and insights.
              </p>
            </div>
          </div>

          {/* Input Mode */}
          <div className="mb-5 flex rounded-xl bg-slate-100 p-1">
            <button
              type="button"
              onClick={() => setInputMode("text")}
              className={`flex flex-1 items-center justify-center gap-2 rounded-lg px-4 py-2.5 text-sm font-semibold transition ${
                inputMode === "text"
                  ? "bg-white text-blue-600 shadow-sm"
                  : "text-slate-500 hover:text-slate-700"
              }`}
            >
              <FileText className="h-4 w-4" />
              Text Input
            </button>

            <button
              type="button"
              onClick={() => setInputMode("url")}
              className={`flex flex-1 items-center justify-center gap-2 rounded-lg px-4 py-2.5 text-sm font-semibold transition ${
                inputMode === "url"
                  ? "bg-white text-blue-600 shadow-sm"
                  : "text-slate-500 hover:text-slate-700"
              }`}
            >
              <Link2 className="h-4 w-4" />
              URL Input
            </button>
          </div>

          {/* Text Input */}
          {inputMode === "text" && (
            <div>
              <div className="mb-2 flex items-center justify-between">
                <label className="text-sm font-semibold text-slate-800">
                  Enter Cultural Content
                </label>

                <span className="text-xs text-slate-400">
                  Short statement or longer paragraph
                </span>
              </div>

              <textarea
                value={content}
                onChange={handleContentChange}
                placeholder="Type or paste a cultural statement or paragraph here..."
                className="min-h-[205px] w-full resize-none rounded-xl border border-slate-200 bg-slate-50/50 p-4 text-sm leading-6 text-slate-900 outline-none transition placeholder:text-slate-400 focus:border-blue-500 focus:bg-white focus:ring-4 focus:ring-blue-50"
              />

              <div className="mt-2 flex items-center justify-between text-xs text-slate-400">
                <span>
                  Example: Chinese people always drink tea every day.
                </span>

                <span>
                  {content.length}/{maxLength}
                </span>
              </div>
            </div>
          )}

          {/* URL Input */}
          {inputMode === "url" && (
            <div>
              <div className="mb-2 flex items-center justify-between">
                <label className="text-sm font-semibold text-slate-800">
                  Analyze Content from URL
                </label>

                <span className="text-xs text-slate-400">
                  Website, article or public post
                </span>
              </div>

              <div className="flex gap-2">
                <div className="relative flex-1">
                  <Link2 className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />

                  <input
                    type="url"
                    value={url}
                    onChange={(e) => setUrl(e.target.value)}
                    placeholder="https://example.com/cultural-content"
                    className="h-12 w-full rounded-xl border border-slate-200 bg-slate-50/50 pl-11 pr-4 text-sm text-slate-900 outline-none transition placeholder:text-slate-400 focus:border-blue-500 focus:bg-white focus:ring-4 focus:ring-blue-50"
                  />
                </div>

                <button
                  type="button"
                  className="h-12 rounded-xl border border-blue-200 bg-blue-50 px-5 text-sm font-semibold text-blue-600 transition hover:bg-blue-100"
                >
                  Fetch
                </button>
              </div>

              <p className="mt-2 text-xs text-slate-400">
                Paste a publicly accessible URL containing cultural content.
              </p>
            </div>
          )}

          {/* Select Fields */}
          <div className="mt-6 grid gap-4 md:grid-cols-2">
            {/* Content Type */}
            <div>
              <label className="mb-2 block text-sm font-semibold text-slate-800">
                Content Type
              </label>

              <div className="relative">
                <select
                  value={contentType}
                  onChange={(e) => setContentType(e.target.value)}
                  className="h-12 w-full appearance-none rounded-xl border border-slate-200 bg-white px-4 pr-10 text-sm text-slate-700 outline-none transition focus:border-blue-500 focus:ring-4 focus:ring-blue-50"
                >
                  {contentTypes.map((type) => (
                    <option key={type} value={type}>
                      {type}
                    </option>
                  ))}
                </select>

                <ChevronDown className="pointer-events-none absolute right-4 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
              </div>
            </div>

            {/* Target Audience */}
            <div>
              <label className="mb-2 block text-sm font-semibold text-slate-800">
                Target Audience
              </label>

              <div className="relative">
                <select
                  value={targetAudience}
                  onChange={(e) => setTargetAudience(e.target.value)}
                  className="h-12 w-full appearance-none rounded-xl border border-slate-200 bg-white px-4 pr-10 text-sm text-slate-700 outline-none transition focus:border-blue-500 focus:ring-4 focus:ring-blue-50"
                >
                  {targetAudiences.map((audience) => (
                    <option key={audience} value={audience}>
                      {audience}
                    </option>
                  ))}
                </select>

                <ChevronDown className="pointer-events-none absolute right-4 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
              </div>
            </div>
          </div>

          {/* Evaluate Button */}
          <button
            type="button"
            onClick={handleEvaluate}
            className="mt-6 flex h-13 w-full items-center justify-center gap-2 rounded-xl bg-blue-600 px-5 text-sm font-semibold text-white shadow-sm transition hover:bg-blue-700 hover:shadow-md active:scale-[0.99]"
          >
            <Sparkles className="h-4 w-4" />
            Evaluate Content
          </button>
        </section>

        {/* Sample Examples */}
        <section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
          <div className="mb-5 flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-amber-50">
              <Lightbulb className="h-5 w-5 text-amber-500" />
            </div>

            <div>
              <h2 className="text-xl font-bold text-slate-900">
                Sample Examples
              </h2>

              <p className="mt-1 text-xs text-slate-500">
                Try an example to see how the evaluator works.
              </p>
            </div>
          </div>

          <div className="grid gap-4 md:grid-cols-3">
            <SampleCard
              text="Chinese people always drink tea. It is a simple and traditional habit."
              type="General Post"
              tag="Potential Generalization"
              onClick={() =>
                onContentChange?.(
                  "Chinese people always drink tea. It is a simple and traditional habit."
                )
              }
            />

            <SampleCard
              text="The Spring Festival is an important traditional festival in China, and many families celebrate it together."
              type="Cultural Introduction"
              tag="Cultural Introduction"
              onClick={() =>
                onContentChange?.(
                  "The Spring Festival is an important traditional festival in China, and many families celebrate it together."
                )
              }
            />

            <SampleCard
              text="All Chinese people are good at mathematics."
              type="General Post"
              tag="Potential Stereotype"
              onClick={() =>
                onContentChange?.(
                  "All Chinese people are good at mathematics."
                )
              }
            />
          </div>
        </section>
      </div>

      {/* ================= RIGHT COLUMN ================= */}
      <section className="min-w-0 rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
        {/* Results Header */}
        <div className="mb-5 flex items-start justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-emerald-50">
              <BarChart3 className="h-5 w-5 text-emerald-600" />
            </div>

            <div>
              <h2 className="text-xl font-bold text-slate-900">
                Evaluation Results
              </h2>

              <p className="mt-1 text-xs text-slate-500">
                AI-powered cultural content analysis
              </p>
            </div>
          </div>

          <span className="whitespace-nowrap text-xs text-slate-400">
            Dec 2, 2025 · 15:42
          </span>
        </div>

        {!evaluated ? (
              /* Empty State */
              <div className="flex min-h-[470px] flex-col items-center justify-center rounded-xl border border-dashed border-slate-200 bg-slate-50/40 px-8 text-center">
                <div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-blue-50">
                  <Sparkles className="h-7 w-7 text-blue-500" />
                </div>

                <h3 className="mt-5 text-lg font-bold tracking-tight text-slate-900">
                  Ready to evaluate
                </h3>

                <p className="mt-2 max-w-sm text-sm leading-6 text-slate-500">
                  Enter cultural content on the left and click{" "}
                  <span className="font-semibold text-slate-700">
                    Evaluate Content
                  </span>{" "}
                  to see the AI-powered analysis.
                </p>

                <div className="mt-6 flex items-center gap-2 rounded-full border border-slate-200 bg-white px-4 py-2 text-xs text-slate-500 shadow-sm">
                  <span className="h-2 w-2 rounded-full bg-emerald-500" />
                  AI evaluator is ready
                </div>
              </div>
            ) : (
          /* Results */
          <div className="space-y-5">
            {/* Score + Risk */}
            <div className="grid gap-3 sm:grid-cols-2">
              <div className="rounded-xl border border-emerald-100 bg-emerald-50/70 p-5">
                <p className="text-xs font-semibold text-emerald-700">
                  Overall Score
                </p>

                <div className="mt-1 flex items-baseline gap-1">
                  <span className="text-4xl font-bold tracking-tight text-emerald-700">
                    78
                  </span>

                  <span className="text-sm font-semibold text-emerald-600">
                    / 100
                  </span>
                </div>
              </div>

              <div className="rounded-xl border border-amber-100 bg-amber-50/70 p-5">
                <div className="flex items-center gap-2">
                  <AlertTriangle className="h-4 w-4 text-amber-600" />

                  <span className="rounded-full bg-amber-200 px-3 py-1 text-xs font-bold text-amber-800">
                    Moderate Risk
                  </span>
                </div>

                <p className="mt-3 text-xs text-amber-700">
                  Some cultural issues detected
                </p>
              </div>
            </div>

            {/* Dimension Scores */}
            <div>
              <h3 className="mb-4 text-sm font-bold text-slate-900">
                Dimension Scores
              </h3>

              <div className="space-y-4">
                <ScoreBar label="Cultural Accuracy" score={85} />
                <ScoreBar label="Avoids Generalization" score={70} />
                <ScoreBar label="Bias & Stereotypes" score={60} />
                <ScoreBar label="Cross-cultural Clarity" score={80} />
                <ScoreBar label="Misunderstanding Risk" score={65} />
                <ScoreBar label="Communication Quality" score={90} />
              </div>
            </div>

            {/* AI Analysis */}
            <div className="rounded-xl border border-slate-200 bg-slate-50/60 p-4">
              <div className="flex items-center gap-2">
                <CheckCircle2 className="h-5 w-5 text-blue-600" />

                <h3 className="text-sm font-bold text-slate-900">
                  AI Analysis
                </h3>
              </div>

              <p className="mt-3 text-sm leading-6 text-slate-600">
                The content correctly mentions tea as a traditional part of
                Chinese culture, which is accurate. However, the phrase
                “Chinese people always drink tea” is a bit too general and may
                not apply to everyone. A more specific and inclusive expression
                is recommended.
              </p>
            </div>

            {/* Suggestions */}
            <div>
              <div className="flex items-center gap-2">
                <Lightbulb className="h-5 w-5 text-amber-500" />

                <h3 className="text-sm font-bold text-slate-900">
                  Suggestions for Improvement
                </h3>
              </div>

              <div className="mt-3 rounded-xl bg-blue-50 px-4 py-3.5">
                <p className="text-sm leading-6 text-blue-800">
                  Consider using a more nuanced statement, such as:
                  <span className="font-semibold">
                    {" "}
                    “Many Chinese people enjoy drinking tea, which is a
                    traditional and popular part of Chinese culture.”
                  </span>
                </p>
              </div>
            </div>

            {/* Actions */}
            <div className="flex flex-wrap gap-2 border-t border-slate-100 pt-4">
              <button
                type="button"
                className="flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3.5 py-2.5 text-xs font-semibold text-slate-700 transition hover:bg-slate-50"
              >
                <Download className="h-4 w-4" />
                Download Report
              </button>

              <button
                type="button"
                onClick={handleCopy}
                className="flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3.5 py-2.5 text-xs font-semibold text-slate-700 transition hover:bg-slate-50"
              >
                <Copy className="h-4 w-4" />
                Copy Result
              </button>

              <button
                type="button"
                onClick={handleReset}
                className="flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3.5 py-2.5 text-xs font-semibold text-slate-700 transition hover:bg-slate-50"
              >
                <RotateCcw className="h-4 w-4" />
                Evaluate Another
              </button>
            </div>
          </div>
        )}
      </section>
    </div>
  );
}

/* ================= SAMPLE CARD ================= */

function SampleCard({
  text,
  type,
  tag,
  onClick,
}: {
  text: string;
  type: string;
  tag: string;
  onClick: () => void;
}) {
  return (
    <article className="flex flex-col rounded-xl border border-slate-200 bg-slate-50/70 p-4 transition hover:border-blue-200 hover:bg-blue-50/30">
      <p className="min-h-[100px] text-sm leading-6 text-slate-700">
        “{text}”
      </p>

      <div className="mt-4">
        <p className="text-xs font-medium text-slate-500">{type}</p>

        <p className="mt-1 text-xs font-semibold text-amber-600">{tag}</p>
      </div>

      <button
        type="button"
        onClick={onClick}
        className="mt-4 rounded-lg border border-blue-200 bg-white px-4 py-2.5 text-xs font-semibold text-blue-600 transition hover:bg-blue-50"
      >
        Use Example
      </button>
    </article>
  );
}

/* ================= SCORE BAR ================= */

function ScoreBar({
  label,
  score,
}: {
  label: string;
  score: number;
}) {
  return (
    <div>
      <div className="mb-1.5 flex items-center justify-between">
        <span className="text-xs font-medium text-slate-600">{label}</span>

        <span className="text-xs font-bold text-slate-700">{score}</span>
      </div>

      <div className="h-2 overflow-hidden rounded-full bg-slate-100">
        <div
          className="h-full rounded-full bg-blue-600 transition-all duration-700"
          style={{ width: `${score}%` }}
        />
      </div>
    </div>
  );
}